$rows=all('SELECT b.*,s.starts_at,s.ends_at,s.status AS session_status,l.name,t.name AS trainer FROM reservations b JOIN sessions s ON s.id=b.session_id JOIN lessons l ON l.id=s.lesson_id JOIN trainers t ON t.id=s.trainer_id WHERE b.user_id=? ORDER BY s.starts_at DESC',[$u['id']]);
