<div class="table-wrap card"><table><thead><tr><th>Lekce</th><th>Termín</th><th>Stav</th><th>Docházka</th><th>Akce</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['name'])?></strong><small><?=e($r['trainer'])?></small></td><td><?=e(stamp($r['starts_at']))?></td><td><span class="badge <?=$r['status']==='cancelled'?'neutral':''?>"><?=$r['status']==='cancelled'?'Zrušeno':(strtotime($r['ends_at'])<time()?'Proběhlá lekce':'Rezervováno')?></span></td><td><?=$r['status']==='active'?e(attendance_label($r['attendance'])):'—'?></td><td><?php if($r['status']==='active' && strtotime($r['starts_at'])-time()>=7200 && $r['attendance']==='pending'): action_form('cancel_booking',['reservation_id'=>$r['id']],'Zrušit','button small secondary','Opravdu chcete zrušit rezervaci?'); else: ?>—<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php elseif($page==='activity'): heading('KAŽDÝ TRÉNINK SE POČÍTÁ','Moje aktivita','Přehled skutečných návštěv potvrzených správcem.');
$visits=(int)scalar('SELECT COUNT(*) FROM reservations WHERE user_id=? AND status="active" AND attendance="present"',[$u['id']]);
$minutes=(int)scalar('SELECT COALESCE(SUM(TIMESTAMPDIFF(MINUTE,s.starts_at,s.ends_at)),0) FROM reservations b JOIN sessions s ON s.id=b.session_id WHERE b.user_id=? AND b.status="active" AND b.attendance="present"',[$u['id']]);
$future=(int)scalar('SELECT COUNT(*) FROM reservations b JOIN sessions s ON s.id=b.session_id WHERE b.user_id=? AND b.status="active" AND s.status="published" AND s.starts_at>NOW()',[$u['id']]); ?>
<div class="stats"><div class="card"><span>Potvrzené návštěvy</span><strong><?=$visits?></strong></div><div class="card"><span>Minut pohybu</span><strong><?=$minutes?></strong></div><div class="card"><span>Nadcházející rezervace</span><strong><?=$future?></strong></div></div>
<div class="two-col"><section class="card"><h2>Posledních 6 měsíců</h2><div class="bar-chart"><?php $start=(new DateTimeImmutable('first day of this month'))->modify('-5 months'); for($i=0;$i<6;$i++): $a=$start->modify('+'.$i.' months');$b=$a->modify('+1 month');$n=(int)scalar('SELECT COUNT(*) FROM reservations b JOIN sessions s ON s.id=b.session_id WHERE b.user_id=? AND b.status="active" AND b.attendance="present" AND s.starts_at>=? AND s.starts_at<?',[$u['id'],$a->format('Y-m-d'),$b->format('Y-m-d')]); ?><div class="chart-row"><span><?=$a->format('m/Y')?></span><meter min="0" max="<?=max(10,$n)?>" value="<?=$n?>" aria-label="Návštěvy <?=$a->format('m/Y')?>"></meter><strong><?=$n?></strong></div><?php endfor ?></div></section><section class="card"><h2>Historie návštěv</h2><?php $history=all('SELECT l.name,s.starts_at FROM reservations b JOIN sessions s ON s.id=b.session_id JOIN lessons l ON l.id=s.lesson_id WHERE b.user_id=? AND b.status="active" AND b.attendance="present" ORDER BY s.starts_at DESC',[$u['id']]); if(!$history): empty_state('Zatím nemáte potvrzenou návštěvu.'); else: foreach($history as $h): ?><div class="history-row"><strong><?=e($h['name'])?></strong><span><?=e(stamp($h['starts_at']))?></span></div><?php endforeach; endif ?></section></div>
<?php elseif($page==='profile'): heading('VÁŠ ÚČET','Můj profil'); ?>
<div class="two-col"><section class="card"><h2>Osobní údaje</h2><form method="post" class="stack"><?php token() ?><input type="hidden" name="action" value="profile"><?php field('name','Jméno a příjmení','text',$u['name'],true,'maxlength="100"'); field('email','E-mail','email',$u['email'],true,'maxlength="190"') ?><button>Uložit údaje</button></form></section><section class="card"><h2>Změna hesla</h2><form method="post" class="stack"><?php token() ?><input type="hidden" name="action" value="password"><?php field('current_password','Současné heslo','password','',true,'autocomplete="current-password"'); field('password','Nové heslo','password','',true,'minlength="10" maxlength="72" autocomplete="new-password"'); ?><small class="muted">Alespoň 10 znaků, nejvýše 72 bajtů.</small><button>Změnit heslo</button></form></section></div>
